powerpagecomponent.content:
{"source":"<link rel=\"stylesheet\" href=\"/citf-portal.css\" />

<div id=\"citf-page-boot\" aria-live=\"polite\" aria-busy=\"true\"><div class=\"spin\" aria-hidden=\"true\"></div><div>Loading…</div></div>
<script>
(function(){
  function done(){
    var b=document.getElementById('citf-page-boot');
    document.body.classList.add('citf-page-ready');
    if(b){ b.classList.add('hide'); b.setAttribute('aria-busy','false'); setTimeout(function(){ try{b.remove();}catch(e){} }, 350); }
  }
  if(document.readyState==='complete') setTimeout(done, 150);
  else window.addEventListener('load', function(){ setTimeout(done, 150); });
  document.addEventListener('click', function(e){
    var a=e.target && e.target.closest && e.target.closest('a[href]');
    if(!a) return;
    var href=a.getAttribute('href')||'';
    if(!href || href.charAt(0)==='#' || href.indexOf('javascript:')===0 || a.target==='_blank') return;
    try{
      var u=new URL(href, location.href);
      if(u.origin!==location.origin) return;
      if(u.pathname===location.pathname && u.search===location.search) return;
    }catch(err){ return; }
    var b=document.getElementById('citf-page-boot');
    if(!b){
      b=document.createElement('div'); b.id='citf-page-boot';
      b.innerHTML='<div class=\"spin\" aria-hidden=\"true\"></div><div>Loading…</div>';
      document.body.appendChild(b);
    }
    document.body.classList.remove('citf-page-ready');
    b.classList.remove('hide'); b.style.display='flex'; b.setAttribute('aria-busy','true');
  }, true);
})();
</script>

{% assign homeurl = website.adx_partialurl %}
<a class=\"skip\" href=\"#mainContent\">Skip to main content</a>
<header class=\"p-head\" role=\"banner\">
  <div class=\"in\">
    <a class=\"logo\" href=\"/\">
      <span class=\"mark\">LOGO</span>
      <span class=\"logo-text\"><b>CIC Company Portal</b><small>CITF Application Portal &amp; Pre-approved List · Power Pages</small></span>
    </a>
    {% assign path = request.path | default: page.url | default: page.partialurl | downcase %}
    {% assign tab = 'home' %}
    {% if path contains 'my-applications' or path contains 'funding-application' or path contains 'disbursement-request' %}
      {% assign tab = 'apps' %}
    {% elsif path contains 'pre-approved-list' %}
      {% assign tab = 'pal' %}
    {% elsif path contains 'messages' %}
      {% assign tab = 'msg' %}
    {% elsif path contains 'company-registration' or path contains 'track' %}
      {% assign tab = 'reg' %}
    {% endif %}
    <nav class=\"p-nav\" aria-label=\"Main\">
      {% if user %}
        <a href=\"/\" data-nav=\"home\" {% if tab == 'home' %}class=\"on\" aria-current=\"page\"{% endif %}>My Company</a>
        <a href=\"/my-applications/\" data-nav=\"apps\" {% if tab == 'apps' %}class=\"on\" aria-current=\"page\"{% endif %}>CITF Applications</a>
        <a href=\"/pre-approved-list/\" data-nav=\"pal\" {% if tab == 'pal' %}class=\"on\" aria-current=\"page\"{% endif %}>Pre-approved List</a>
        <a href=\"/messages/\" data-nav=\"msg\" {% if tab == 'msg' %}class=\"on\" aria-current=\"page\"{% endif %}>Messages</a>
        <span class=\"who\">| {{ user.fullname | escape }}</span>
        <a href=\"{% if homeurl %}/{{ homeurl }}{% endif %}{{ website.sign_out_url_substitution }}\">Sign out</a>
      {% else %}
        <a href=\"/\" {% if tab == 'home' %}class=\"on\" aria-current=\"page\"{% endif %}>Sign in</a>
        <a href=\"/company-registration/\" data-nav=\"reg\" {% if tab == 'reg' %}class=\"on\" aria-current=\"page\"{% endif %}>Register company</a>
      {% endif %}
    </nav>
  </div>
</header>
<script>
(function () {
  var path = (location.pathname || \"/\").toLowerCase();
  var tab = \"home\";
  if (/my-applications|funding-application|disbursement-request/.test(path)) tab = \"apps\";
  else if (path.indexOf(\"pre-approved-list\") !== -1) tab = \"pal\";
  else if (path.indexOf(\"messages\") !== -1) tab = \"msg\";
  else if (/company-registration|track/.test(path)) tab = \"reg\";
  var links = document.querySelectorAll(\".p-nav a[data-nav]\");
  for (var i = 0; i < links.length; i++) {
    var on = links[i].getAttribute(\"data-nav\") === tab;
    links[i].classList.toggle(\"on\", on);
    if (on) links[i].setAttribute(\"aria-current\", \"page\");
    else links[i].removeAttribute(\"aria-current\");
  }
})();
</script>
"}
